// Models that must not be invoked, whatever the request says.
// A missing card, a prohibited tier, or a high-risk deployment with no reviewer
// is a forbid. A permit later in the bundle cannot override these.

// @id R-PROHIBITED
// @controls EU-5
forbid (
  principal,
  action,
  resource
)
when {
  resource.risk_tier == "unacceptable"
};

// @id R-CARD-INCOMPLETE
// @controls EU-11
forbid (
  principal,
  action,
  resource
)
when {
  resource.card_complete == false
};

// @id R-OVERSIGHT
// @controls EU-14
forbid (
  principal,
  action,
  resource
)
when {
  resource.risk_tier == "high" && resource.human_oversight == false
};

// @id R-RESTRICTED-BLOCK
// @controls EU-10
forbid (
  principal,
  action == Action::"invoke",
  resource
)
when {
  context.data_class == "RESTRICTED"
};

// EU confidential and restricted payloads stay in eu-central-1.
// This file is the one a weakened candidate deletes. The permit in
// 003-permits.cedar would allow the US model for customer support.
// Forbid wins while this file is loaded. Without it, that permit allows
// the EU confidential ticket to leave the region.

// @id R-RESIDENCY-EU
// @controls EU-10
forbid (
  principal,
  action == Action::"invoke",
  resource
)
when {
  context.data_residency == "EU" &&
  resource.region != "eu-central-1" &&
  context.data_class in ["CONFIDENTIAL", "RESTRICTED"]
};

// Permits are narrow on purpose, except the hosted support permit, which is
// deliberately wide so the residency forbid has something to override.
// No matching permit is a deny (R-DEFAULT-DENY). There is no "allow all".

// @id R-PERMIT-SUPPORT-EU
// @controls EU-9
permit (
  principal,
  action == Action::"invoke",
  resource == Model::"atlas-eu-mini"
)
when {
  context.purpose == "customer_support" &&
  context.data_class in ["PUBLIC", "INTERNAL", "CONFIDENTIAL"]
};

// @id R-PERMIT-HOSTED-SUPPORT
// @controls EU-9
permit (
  principal,
  action == Action::"invoke",
  resource == Model::"frontier-us-large"
)
when {
  context.purpose == "customer_support" &&
  context.data_class in ["PUBLIC", "INTERNAL", "CONFIDENTIAL", "RESTRICTED"]
};

// @id R-PERMIT-PUBLIC-US
// @controls EU-13
permit (
  principal,
  action == Action::"invoke",
  resource == Model::"frontier-us-large"
)
when {
  context.purpose == "public_faq" &&
  context.data_class == "PUBLIC"
};

// @id R-PERMIT-CREDIT
// @controls EU-14
permit (
  principal,
  action == Action::"invoke",
  resource == Model::"credit-eu-scorer"
)
when {
  context.purpose == "credit_decision" &&
  context.data_residency == "EU" &&
  context.data_class in ["INTERNAL", "CONFIDENTIAL"]
};

// @id R-PERMIT-CLAIMS
// @controls EU-14
permit (
  principal,
  action == Action::"invoke",
  resource == Model::"claims-triage-eu"
)
when {
  context.purpose == "claims_triage" &&
  context.data_residency == "EU" &&
  context.data_class in ["PUBLIC", "INTERNAL", "CONFIDENTIAL"]
};

